package dev.pocketengine.features.assistant;

import android.app.Application;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.FeatureContext;
import dev.pocketengine.features.FeatureHost;
import dev.pocketengine.features.MemorySourceBridge;
import dev.pocketengine.features.memory.ConversationHistory;
import dev.pocketengine.features.memory.MemoryBook;
import dev.pocketengine.features.memory.SourceRef;
import dev.pocketengine.features.memory.TaskMemoryNativeHost;
import dev.pocketengine.store.SecretVault;
import dev.pocketengine.store.SettingsStore;
import dev.pocketengine.store.TaskStore;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.concurrent.atomic.AtomicInteger;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;
import static org.junit.Assert.*;

/** Original DB/native owner host, no model, new authority, device or physical-I/O proof. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class OwnerOriginalSearchNativeTest {
    private static JSONObject options(String query,String cursor,int limit,int chars)throws Exception{return new JSONObject().put("query",query).put("cursor",cursor).put("limit",limit).put("maxChars",chars);}
    private static SourceRef ref(String id,long revision){return new SourceRef("message",id,revision,"owner","private");}
    private static final class Fixture implements AutoCloseable {
        final Context android=RuntimeEnvironment.getApplication();TaskStore tasks;AssistantModule assistant;ConversationRepository repo;SQLiteDatabase db;FeatureHost host;TaskMemoryNativeHost nativeHost;
        Fixture()throws Exception{this(null);}
        Fixture(byte[] legacy)throws Exception{android.deleteDatabase("pocket-world.db");File old=new File(android.getFilesDir(),"private_conversations.json");if(legacy!=null)Files.write(old.toPath(),legacy);open();}
        void reopen()throws Exception{close();open();}
        void open()throws Exception{tasks=new TaskStore(android);assistant=new AssistantModule(new FeatureContext(android,new SettingsStore(android),new SecretVault(android),event->{}),null,null,tasks);repo=tasks.conversationRepository();var f=TaskStore.class.getDeclaredField("db");f.setAccessible(true);db=(SQLiteDatabase)f.get(tasks);host=new FeatureHost(event->{});host.register(assistant);var bridge=new MemorySourceBridge(host,tasks);bridge.bindAssistant(assistant);nativeHost=new TaskMemoryNativeHost(host,tasks,bridge);}
        void conversation(String id)throws Exception{repo.transaction(()->{repo.saveConversation(new JSONObject().put("conversationId",id).put("title","私人原会话 "+id).put("messages",new JSONArray()));return null;});}
        void save(String conversation,String id,long version,String body)throws Exception{repo.transaction(()->{repo.saveSource(ref(id,version).toJson().put("conversationId",conversation).put("role","user").put("deleted",false));repo.saveMessage(conversation,new JSONObject().put("id",id).put("revision",version).put("role","user").put("content",body));return null;});}
        JSONObject search(String term,String cursor,int limit,int chars)throws Exception{return nativeHost.handle("searchOwnerOriginals",options(term,cursor,limit,chars),new RunControl());}
        JSONObject read(JSONObject hit,int offset,int chars)throws Exception{return nativeHost.handle("readOwnerOriginalSearchHit",new JSONObject().put("ownerLocator",hit.getJSONObject("ownerLocator")).put("offset",offset).put("maxChars",chars),new RunControl());}
        public void close(){assistant.close();host.close();db.close();}
    }
    @Test public void actualNativeOwnerFindsTwoVersionsAcrossMoreThanRecentConversationAndMessageWindows()throws Exception{try(Fixture f=new Fixture()){for(int i=0;i<24;i++){String c="c-"+i;f.conversation(c);f.save(c,String.format(java.util.Locale.ROOT,"message-%04d",i),9_000_000_000L,i==0?"rev1 Aster 的原因是离线旧报告":i==23?"rev2 Cobalt 的原因是新确认事实":"普通原话");}for(int i=24;i<110;i++)f.save("c-0",String.format(java.util.Locale.ROOT,"message-%04d",i),1,"最近窗口内普通消息");f.reopen();JSONObject first=f.search("原因","",20,16000);assertEquals(2,first.getJSONArray("entries").length());assertTrue(first.getBoolean("ownerOnly"));assertFalse(first.getBoolean("modelReferenceRegistered"));JSONObject old=first.getJSONArray("entries").getJSONObject(0);assertEquals(9_000_000_000L,old.getLong("historicalRevision"));assertFalse(old.has("sourceRef"));assertFalse(old.has("sourceJump"));assertEquals("rev1 Aster 的原因是离线旧报告",f.read(old,0,16000).getString("body"));assertEquals(80,f.assistant.readOriginalConversation("c-0","",80).getJSONArray("messages").length());}}
    @Test public void sparseQueryAdvancesOnlyScannedIdsAndCanFindBeyondFirstHundred()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");for(int i=0;i<130;i++)f.save("c",String.format(java.util.Locale.ROOT,"key-%04d",i),1,i==125?"唯一旧原因":"不匹配");JSONObject first=f.search("唯一旧原因","",20,16000);assertEquals(0,first.getJSONArray("entries").length());assertEquals(100,first.getJSONObject("pageCoverage").getInt("scannedRows"));assertTrue(first.getBoolean("hasMore"));JSONObject next=f.search("唯一旧原因",first.getString("nextCursor"),20,16000);assertEquals(1,next.getJSONArray("entries").length());assertFalse(next.getBoolean("hasMore"));assertEquals("唯一旧原因",next.getJSONArray("entries").getJSONObject(0).getString("body"));assertFalse(next.getJSONObject("pageCoverage").getBoolean("completeHistory"));}}
    @Test public void retirementStaysOwnerVisibleButDoesNotReauthorizeDerivedModelHistory()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","owner-retired",1,"主人仍可看的私人旧原话");f.assistant.retireMemoryContexts(new JSONArray().put(new JSONObject().put("sourceRefs",new JSONArray().put(ref("owner-retired",1).toJson()))),"owner_forget");JSONObject found=f.search("私人旧原话","",20,16000).getJSONArray("entries").getJSONObject(0);assertEquals("retired_for_derived_context",found.getString("derivedUseStatus"));assertEquals("主人仍可看的私人旧原话",f.read(found,0,16000).getString("body"));assertThrows(Exception.class,()->f.assistant.readMemorySource(ref("owner-retired",1)));JSONObject model=f.assistant.queryRetainedHistory(f.assistant.openHistoryConversation("c"),options("私人旧原话","",20,16000),new RunControl());assertEquals(0,model.getJSONArray("entries").length());}}
    @Test public void deletingMessageOrContainerNeverReturnsCachedOwnerHitBody()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","delete-one",1,"要删除的原话");JSONObject hit=f.search("原话","",20,16000).getJSONArray("entries").getJSONObject(0);f.assistant.handle("deleteMessage",new JSONObject().put("conversationId","c").put("messageId","delete-one").put("revision",1));assertFalse(f.read(hit,0,16000).has("body"));assertEquals(0,f.search("原话","",20,16000).getJSONArray("entries").length());f.save("c","delete-two",1,"新原话");JSONObject second=f.search("新原话","",20,16000).getJSONArray("entries").getJSONObject(0);f.assistant.handle("delete",new JSONObject().put("conversationId","c"));assertFalse(f.read(second,0,16000).has("body"));}}
    @Test public void changedRevisionAndSameRevisionChangedHashRefuseNewBodyUntilFreshSearch()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","changing",1,"旧原因 Aster");JSONObject hit=f.search("原因","",20,16000).getJSONArray("entries").getJSONObject(0);f.save("c","changing",2,"新原因 Cobalt");JSONObject changed=f.read(hit,0,16000);assertEquals("source_changed",changed.getString("status"));assertFalse(changed.has("body"));JSONObject fresh=f.search("原因","",20,16000).getJSONArray("entries").getJSONObject(0);f.db.execSQL("UPDATE assistant_messages SET body=?,body_sha=?,body_bytes=? WHERE source_id=?",new Object[]{"同修订但正文已变","sha256:"+ConversationRepository.shaBytes("同修订但正文已变".getBytes(StandardCharsets.UTF_8)),"同修订但正文已变".getBytes(StandardCharsets.UTF_8).length,"changing"});assertFalse(f.read(fresh,0,16000).has("body"));}}
    @Test public void unverifiedImportedOriginalsAreFindableWithByteIdentityButNoHistoricalSourceRef()throws Exception{byte[] bytes="[{\"title\":\"旧原件\",\"messages\":[{\"role\":\"user\",\"content\":\"旧格式仍要找到的原话\"}]}]".getBytes(StandardCharsets.UTF_8);try(Fixture f=new Fixture(bytes)){assertThrows(Exception.class,()->f.search("原话","",20,16000));JSONObject review=f.assistant.reviewOriginalHistoryMigration();f.assistant.activateOriginalHistoryMigration(review.getString("migrationTaskId"),review.getString("sourceSha256"),true);JSONObject hit=f.search("原话","",20,16000).getJSONArray("entries").getJSONObject(0);assertTrue(hit.getBoolean("importAssignedIdentity"));assertFalse(hit.getBoolean("historicalRevisionKnown"));assertTrue(hit.isNull("historicalRevision"));assertFalse(hit.has("sourceRef"));assertFalse(hit.has("sourceJump"));JSONObject original=f.read(hit,0,16000);assertEquals("旧格式仍要找到的原话",original.getString("body"));assertEquals(ConversationRepository.shaBytes(bytes),original.getJSONObject("originalByteReference").getString("sourceSha256"));f.assistant.deleteOriginalImportedRecord(hit.getString("conversationId"),hit.getString("recordId"),hit.getLong("recordVersion"));assertFalse(f.read(hit,0,16000).has("body"));assertEquals(0,f.search("原话","",20,16000).getJSONArray("entries").length());}}
    @Test public void ownerCommandsDoNotEnterModelModuleAndNeedActualNativeOwnerControl()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","only-owner",1,"私人原文");JSONObject query=options("私人","",20,16000);assertThrows(Exception.class,()->f.assistant.handle("searchOwnerOriginals",query));assertThrows(Exception.class,()->f.nativeHost.handle("searchOwnerOriginals",query));RunControl model=new RunControl();model.bindHostRun("model-task","model-run",1);assertThrows(Exception.class,()->f.nativeHost.handle("searchOwnerOriginals",query,model));assertThrows(Exception.class,()->f.nativeHost.handle("searchOwnerOriginals",new JSONObject(query.toString()).put("spaceId","other"),new RunControl()));assertEquals(1,f.nativeHost.handle("searchOwnerOriginals",query,new RunControl()).getJSONArray("entries").length());}}
    @Test public void rowByteAndUnicodeBudgetsDoNotAdvancePastUndeliveredBodies()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","a-oversized",1,"超大"+"中".repeat(360000));f.save("c","b",1,"budget🙂"+"a".repeat(600000));f.save("c","c",1,"budget🙂"+"b".repeat(600000));JSONObject first=f.search("budget","",20,16000);assertEquals(1,first.getJSONArray("entries").length());assertEquals("source_byte_budget",first.getString("reason"));assertTrue(first.getJSONObject("pageCoverage").getLong("materializedOriginalRecordUtf8Bytes")<=1_048_576);JSONObject next=f.search("budget",first.getString("nextCursor"),20,16000);assertEquals(1,next.getJSONArray("entries").length());assertEquals("c",next.getJSONArray("entries").getJSONObject(0).getString("recordId"));JSONObject hit=first.getJSONArray("entries").getJSONObject(0);JSONObject range=f.read(hit,0,64);assertTrue(StandardCharsets.UTF_8.newEncoder().canEncode(range.getString("body")));assertEquals(range.getString("body").length(),range.getJSONObject("readRange").getInt("chars"));assertThrows(Exception.class,()->f.read(hit,7,64));}}
    @Test public void cancelledOrPauseResumedOwnerReadNeverPublishesLateCrossConversationBody()throws Exception{for(boolean pause:new boolean[]{false,true})try(Fixture f=new Fixture()){f.conversation("c");f.save("c","late",1,"迟回原话");RunControl original=new RunControl();AtomicInteger checks=new AtomicInteger();var clocked=new ConversationRepository(f.db,f.tasks,()->{if(checks.incrementAndGet()==2){if(pause){original.pause();original.resume();}else original.cancel();}return 0;});assertThrows(Exception.class,()->clocked.searchOwnerOriginals(options("原话","",20,16000),original));}}
    @Test public void deadlineKeepsDeliveredHitsAndCursorResumesAfterThemWithoutSilentLoss()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","cause-a",1,"原因一");f.save("c","cause-b",1,"原因二");AtomicInteger calls=new AtomicInteger();var clocked=new ConversationRepository(f.db,f.tasks,()->calls.incrementAndGet()<=2?0:600_000_000L);JSONObject first=clocked.searchOwnerOriginals(options("原因","",20,16000),new RunControl());assertEquals(1,first.getJSONArray("entries").length());assertTrue(first.getBoolean("hasMore"));assertEquals("原因一",first.getJSONArray("entries").getJSONObject(0).getString("body"));JSONObject next=f.search("原因",first.getString("nextCursor"),20,16000);assertEquals(1,next.getJSONArray("entries").length());assertEquals("原因二",next.getJSONArray("entries").getJSONObject(0).getString("body"));}}
    @Test public void cursorPinsQueryGenerationAndUpperIdsButUnrelatedTailDoesNotRevokeOldHit()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","a",1,"原话 A");f.save("c","b",1,"原话 B");JSONObject first=f.search("原话","",1,16000),hit=first.getJSONArray("entries").getJSONObject(0);f.save("c","z-new-tail",1,"原话 新尾");assertEquals("原话 A",f.read(hit,0,16000).getString("body"));JSONObject next=f.search("原话",first.getString("nextCursor"),20,16000);assertEquals(1,next.getJSONArray("entries").length());assertEquals("b",next.getJSONArray("entries").getJSONObject(0).getString("recordId"));assertThrows(Exception.class,()->f.search("另一个词",first.getString("nextCursor"),20,16000));}}
    @Test public void sourcePermissionIsNativePrivateAndChangedLocatorCannotOpenAnotherBody()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","exact",1,"完整原话");assertThrows(Exception.class,()->f.repo.transaction(()->{f.repo.saveSource(new SourceRef("message","group-source",1,"owner","group:foreign").toJson().put("conversationId","c").put("role","user").put("deleted",false));return null;}));JSONObject hit=f.search("原话","",20,16000).getJSONArray("entries").getJSONObject(0);JSONObject wrong=new JSONObject(hit.toString());wrong.getJSONObject("ownerLocator").put("conversationId","other");assertFalse(f.read(wrong,0,16000).has("body"));wrong=new JSONObject(hit.toString());wrong.getJSONObject("ownerLocator").put("sourceRef",ref("exact",1).toJson());JSONObject supplied=wrong;assertThrows(Exception.class,()->f.read(supplied,0,16000));}}
    @Test public void boundedPrimaryKeyPlanAndFreshProducerIdentitiesAreReal()throws Exception{try(Fixture f=new Fixture()){String root=OwnerOriginalSearchNativeTest.class.getResource("/"+OwnerOriginalSearchNativeTest.class.getName().replace('.','/')+".class").toString().split("dev/pocketengine/")[0];for(Class<?> actual:new Class<?>[]{OriginalHistorySearch.class,ConversationRepository.class,AssistantModule.class,TaskMemoryNativeHost.class})assertTrue(actual.getName(),actual.getResource("/"+actual.getName().replace('.','/')+".class").toString().startsWith(root));try(Cursor plan=f.db.rawQuery("EXPLAIN QUERY PLAN SELECT source_id FROM assistant_messages WHERE generation=? AND source_id>? AND source_id<=? ORDER BY source_id LIMIT 101",new String[]{"native","a","z"})){String evidence="";while(plan.moveToNext())evidence+=plan.getString(3);assertTrue(evidence,evidence.contains("SEARCH"));assertFalse(evidence,evidence.contains("TEMP B-TREE"));}}}
    @Test public void largeDeepRangesUseVerifiedSubstringsAndKeepExactUtf16AcrossBlockBoundary()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");String body="a".repeat(4095)+"🙂"+"b".repeat(610000)+"尾因🙂";f.save("c","deep-large",1,body);JSONObject hit=f.search("尾因","",1,16000).getJSONArray("entries").getJSONObject(0);int offset=hit.getJSONObject("readRange").getInt("offset");JSONObject deep=f.read(hit,offset,64);assertEquals(body.substring(offset,offset+64),deep.getString("body"));assertEquals(body.length(),deep.getJSONObject("readRange").getInt("totalChars"));assertEquals("verified_native_SQL_substr_blocks",deep.getString("readMode"));assertFalse(deep.getBoolean("fullOriginalMaterializedInApp"));assertTrue(deep.getLong("applicationMaterializedSqlBlockUtf8Bytes")<50_000);assertFalse(deep.getBoolean("sqlInternalWorkMeasured"));assertFalse(deep.getBoolean("physicalIoMeasured"));JSONObject crossing=f.read(hit,4094,64);assertEquals(body.substring(4094,4158),crossing.getString("body"));assertTrue(StandardCharsets.UTF_8.newEncoder().canEncode(crossing.getString("body")));assertThrows(Exception.class,()->f.read(hit,4096,64));}}
    @Test public void derivedRangeHintsAreRebuildableNotAuthorityAndChangedBlockCannotPublish()throws Exception{try(Fixture f=new Fixture()){f.conversation("c");f.save("c","hint-source",1,"原话数据"+"x".repeat(100));JSONObject hit=f.search("原话","",1,16000).getJSONArray("entries").getJSONObject(0),request=new JSONObject().put("ownerLocator",hit.getJSONObject("ownerLocator")).put("offset",0).put("maxChars",64);var fresh=new ConversationRepository(f.db,f.tasks);JSONObject missing=fresh.readOwnerSearchHit(request,new RunControl());assertEquals("current",missing.getString("status"));assertTrue(missing.getBoolean("rangeHintsRebuilt"));assertEquals("bounded_native_full_original_hint_rebuild",missing.getString("readMode"));assertTrue(missing.getString("body").startsWith("原话数据"));assertEquals("verified_native_SQL_substr_blocks",fresh.readOwnerSearchHit(request,new RunControl()).getString("readMode"));f.db.execSQL("UPDATE assistant_messages SET body=? WHERE source_id=?",new Object[]{"替代正文"+"y".repeat(100),"hint-source"});JSONObject rejected=fresh.readOwnerSearchHit(request,new RunControl());assertEquals("source_changed",rejected.getString("status"));assertFalse(rejected.has("body"));}}

}
